// Andes-CSR capability gating.
//
// A core implements an Andes custom CSR only when the matching feature is
// configured into it (config.inc). Restoring a CSR the target core lacks can
// hang the DMI handshake -- observed on ax45mpv_premium for ucode (no DSP) and
// mecc_code (no ECC). So the resume/drain loops transport only the CSRs the
// target core supports, decided here from the core's feature gates.
//
// This header is Verilator/SystemC-free: it maps a CSR address to its gate and
// answers "does a core with these gates support this CSR". The binding of each
// gate to the core's compiled-in `_NDS_*` config macros lives in the sim binary
// (see andes_caps_from_config), so this stays unit-testable in isolation.
#ifndef ANDES_HYBRID_ANDES_CAPS_HPP
#define ANDES_HYBRID_ANDES_CAPS_HPP

#include <cstdint>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace hybrid {

// The hardware feature that gates each transported CSR. ALWAYS = unconditionally
// present (a base machine CSR every core has; never gated off). The first block
// gates the v3 Andes custom CSRs; the second block (UMODE..TRIGGER) gates the v4
// M-ext CSRs (HYBRID_M_EXT_CSR_LIST) -- standard + Andes M-mode CSRs whose
// existence depends on a privilege level or extension the core may not have.
enum class AndesGate : uint8_t {
  ALWAYS = 0,
  DSP,
  CODENSE,
  ZCMT,        // standard Zcmt table jump (jvt); NOT implied by CoDense
  POWERBRAKE,
  STACKSAFE,
  ECC,
  PMA,
  ILM,
  DLM,
  PERF_MONITOR,
  // v4 M-ext gates.
  UMODE,       // needs U-mode  (NDS_NUM_PRIVILEGE_LEVELS >= 2)
  SMODE,       // needs S-mode  (NDS_NUM_PRIVILEGE_LEVELS == 3)
  EPMP,        // ePMP / Smepmp (mseccfg)
  SMRNMI,      // resumable NMI (mnscratch/mnepc/mncause/mnstatus/mnvec/mrnxvec)
  EXCSLVL,     // exception save levels (msave*)
  CLIC,        // CLIC / enhanced CLIC (mtvt/mintthresh/mcirq_entry)
  SMSTATEEN,   // state-enable (mstateen0..3)
  CCTL,        // cache control CSRs (mcctlbeginaddr/mcctldata)
  PPI,         // private peripheral interface base (mppib)
  FIO,         // fast IO base (mfiob)
  TRIGGER,     // debug triggers (tselect/tdata1/tdata2/tcontrol/mcontext)
};

// Map an Andes CSR (by address) to the feature gate that enables it. Addresses
// are the HYBRID_ANDES_CSR_LIST scalars plus the PMA block. A CSR with no
// custom-extension gate is ALWAYS (a base machine CSR every Andes core has).
// Maintainer note: a CSR added to HYBRID_ANDES_CSR_LIST that needs gating must
// get a case here, else it defaults to ALWAYS (transported unconditionally).
constexpr AndesGate andes_gate_for(uint16_t csr_addr)
{
  switch (csr_addr) {
    case 0x801: return AndesGate::DSP;           // ucode (DSP overflow flag)
    case 0x800: return AndesGate::CODENSE;        // uitb  (CoDense table base)
    // jvt is Zcmt's table-jump base, NOT part of classic CoDense (exec.it +
    // uitb): a CoDense core without Zcmt faults a csrr of it (seen on
    // ax45mpv_premium, where it aborted the drain CSR sweep).
    case 0x017: return AndesGate::ZCMT;           // jvt   (Zcmt only)
    case 0x7C5: return AndesGate::POWERBRAKE;     // mpft_ctl
    case 0x7C2: return AndesGate::ECC;            // mecc_code
    case 0x7C6:                                   // mhsp_ctl
    case 0x7C7:                                   // msp_bound
    case 0x7C8: return AndesGate::STACKSAFE;      // msp_base
    case 0x7C0: return AndesGate::ILM;            // milmb (ILM base)
    case 0x7C1: return AndesGate::DLM;            // mdlmb (DLM base)
    // v4 M-ext CSR gates (HYBRID_M_EXT_CSR_LIST).
    // The counter-mask trio mcountermask_m (0x7D1), mcountermask_u (0x7D3),
    // mcounterwen (0x7CE) needs user mode (spec existence: PMNDS & misa[20]);
    // an M-only core does not implement them (a PB csrr faults cmderr=3,
    // aborting a CSR sweep), so gate them UMODE -- not PERF_MONITOR.
    case 0x30A: case 0x306: case 0x7D3:           // menvcfg, mcounteren, mcountermask_u
    case 0x7CE: case 0x7D1:                       // mcounterwen, mcountermask_m
    case 0x808: case 0x80B: case 0x811: case 0x813:  // uzobctl, ucctlbeginaddr, sleepvalue, umisc_ctl
      return AndesGate::UMODE;
    case 0x7D2: case 0x7D5: return AndesGate::SMODE;  // mcountermask_s, mslideleg
    case 0x747: return AndesGate::EPMP;           // mseccfg
    case 0x320: case 0xB03: case 0xB04: case 0xB05: case 0xB06:  // mcountinhibit, mhpmcounter3-6
    case 0x323: case 0x324: case 0x325: case 0x326:              // mhpmevent3-6
    case 0x7CF:                                                  // mcounterinten (PMNDS only)
      return AndesGate::PERF_MONITOR;
    case 0x740: case 0x741: case 0x742: case 0x744:  // mnscratch, mnepc, mncause, mnstatus
    case 0x7C3: case 0x7DE:                           // mnvec, mrnxvec
      return AndesGate::SMRNMI;
    case 0x7C9: return AndesGate::ALWAYS;         // mdcause (base Andes trap CSR)
    case 0x7D6: case 0x7D7: case 0x7D8: case 0x7D9:  // msavestatus, msaveepc1, msavecause1, msaveepc2
    case 0x7DA: case 0x7DB: case 0x7DC:              // msavecause2, msavedcause1, msavedcause2
      return AndesGate::EXCSLVL;
    case 0x307: case 0x347: case 0x7EC:           // mtvt, mintthresh, mcirq_entry
      return AndesGate::CLIC;
    case 0x30C: case 0x30D: case 0x30E: case 0x30F:  // mstateen0..3
      return AndesGate::SMSTATEEN;
    case 0x7CB: case 0x7CD: return AndesGate::CCTL;  // mcctlbeginaddr, mcctldata
    case 0x7F0: return AndesGate::PPI;            // mppib
    case 0x7F1: return AndesGate::FIO;            // mfiob
    case 0x7A0: case 0x7A1: case 0x7A2: case 0x7A5: case 0x7A8:  // tselect, tdata1, tdata2, tcontrol, mcontext
      return AndesGate::TRIGGER;
    default:
      // PMA cfg (0xBC0, 0xBC2) and addr (0xBD0..0xBDF) blocks.
      if (csr_addr == HYBRID_PMA_CFG0_CSR || csr_addr == HYBRID_PMA_CFG0_CSR + 2)
        return AndesGate::PMA;
      if (csr_addr >= HYBRID_PMA_ADDR0_CSR &&
          csr_addr < HYBRID_PMA_ADDR0_CSR + HYBRID_PMA_ADDR_NUM)
        return AndesGate::PMA;
      return AndesGate::ALWAYS;                    // mxstatus 0x7C4, mclk_ctl 0x7DF
  }
}

// The set of Andes feature gates a target core has on. Built from the core's
// compiled-in config (config.inc) in the sim binary and injected into the
// resume/drain loops, so they transport only the CSRs the core implements.
// Default = every gate on (all(): no gating, the prior unconditional behavior).
struct AndesCaps {
  uint32_t gate_mask = ~0u;

  static constexpr AndesCaps all()  { return AndesCaps{~0u}; }
  static constexpr AndesCaps none() { return AndesCaps{0u}; }

  constexpr void set(AndesGate g, bool on = true)
  {
    const uint32_t bit = 1u << static_cast<unsigned>(g);
    if (on) gate_mask |= bit;
    else    gate_mask &= ~bit;
  }

  constexpr bool gate_on(AndesGate g) const
  {
    return (gate_mask >> static_cast<unsigned>(g)) & 1u;
  }

  // ALWAYS-gated CSRs are present on every core regardless of the mask.
  constexpr bool supports_csr(uint16_t csr_addr) const
  {
    const AndesGate g = andes_gate_for(csr_addr);
    return g == AndesGate::ALWAYS || gate_on(g);
  }
};

// The gated CSR names this core supports, for the --describe card. Iterates the
// two single-source-of-truth X-macro lists: the v3 Andes custom CSRs and the v4
// M-ext CSRs. The driver uses this list to gate --verify, so a CSR the core
// lacks is neither restored, drained, nor compared.
inline std::vector<std::string> supported_andes_csr_names(const AndesCaps& caps)
{
  std::vector<std::string> out;
#define X(field, addr, name) if (caps.supports_csr(addr)) out.push_back(name);
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  // PMA group markers (whole pmacfg[]/pmaaddr[] blocks share one gate), so a
  // consumer can include/exclude PMA without listing all 18 entries.
  if (caps.supports_csr(HYBRID_PMA_CFG0_CSR))  out.push_back("pmacfg");
  if (caps.supports_csr(HYBRID_PMA_ADDR0_CSR)) out.push_back("pmaaddr");
  // v4 M-ext CSRs share the same address->gate map and --describe list.
#define X(field, addr, name) if (caps.supports_csr(addr)) out.push_back(name);
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
  return out;
}

}  // namespace hybrid

#endif  // ANDES_HYBRID_ANDES_CAPS_HPP

// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
#define HYBRID_PMP_CFG_NUM  16
#define HYBRID_PMP_ADDR_NUM 64

// v3 Andes CSR block. PMA is 16 entries: pmacfg packs them at one byte each, so
// on RV64 only the even-numbered cfg CSRs exist -- 16 entries live in pmacfg0
// (0xBC0) + pmacfg2 (0xBC2), hence 2 cfg slots; 16 pmaaddr (0xBD0..0xBDF).
#define HYBRID_PMA_CFG_NUM  2
#define HYBRID_PMA_ADDR_NUM 16
#define HYBRID_PMA_CFG0_CSR   0xBC0
#define HYBRID_PMA_ADDR0_CSR  0xBD0

// Single source of truth for the SCALAR Andes CSRs transported in v3: X(field,
// csr_addr, gdb_name). Every consumer (QEMU plugin drain, ResumeDriver restore,
// StateDrain re-read, driver state_diff verify) iterates this list, so adding a
// CSR is one line here -- no consumer edits drift out of sync. PMA (arrays) is
// transported separately, mirroring the existing PMP loops. Each field is a
// 64-bit CSR value; 0 means the producing engine did not implement it (a
// tolerant no-op on restore). Order fixes the struct layout -- append only.
#define HYBRID_ANDES_CSR_LIST(X)            \
  X(mxstatus,       0x7C4, "mxstatus")      \
  X(mpft_ctl,       0x7C5, "mpft_ctl")      \
  X(mclk_ctl,       0x7DF, "mclk_ctl")      \
  X(milmb,          0x7C0, "milmb")         \
  X(mdlmb,          0x7C1, "mdlmb")         \
  X(mecc_code,      0x7C2, "mecc_code")     \
  X(mhsp_ctl,       0x7C6, "mhsp_ctl")      \
  X(msp_bound,      0x7C7, "msp_bound")     \
  X(msp_base,       0x7C8, "msp_base")      \
  X(mcountermask_m, 0x7D1, "mcountermask_m")\
  X(uitb,           0x800, "uitb")          \
  X(jvt,            0x017, "jvt")           \
  X(ucode,          0x801, "ucode")

// The Andes V5 machine/user CSRs a bare-metal Andes core sets up before the ROI
// (boot-static memory system + extension config) plus the DSP overflow flag.
// Restored at resume, re-read at drain, and verified -- live only when
// HYBRID_FLAG_ANDES is set. 13 scalar fields (above) + PMA = 31 * uint64_t.
struct hybrid_andes_csr {
#define HYBRID_ANDES_FIELD(field, addr, name) uint64_t field;
  HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
#undef HYBRID_ANDES_FIELD
  uint64_t pmacfg[HYBRID_PMA_CFG_NUM];
  uint64_t pmaaddr[HYBRID_PMA_ADDR_NUM];
};

// v4: the writable M-mode CSRs across the whole AndeStar V5 SPA that a
// bare-metal M / M+U ROI can hold as plain architectural state -- everything
// the spec defines as readable+writable with no read/write side effects, minus
// the blocks already carried above (standard M trap CSRs, the v3 Andes block,
// PMP, PMA, FP, V). Same single-source-of-truth X-macro pattern as
// HYBRID_ANDES_CSR_LIST: X(field, csr_addr, gdb_name). Every consumer (plugin
// drain, ResumeDriver restore, StateDrain re-read, driver state_diff verify)
// iterates this list, so adding a CSR is one line. Each is capability-gated by
// CSR address (src/hybrid/andes_caps.hpp): an engine that lacks the feature
// no-ops the restore/drain, so the block is transported forward-looking -- a
// core that implements it (CLIC, Smrnmi, Smstateen, ePMP, ...) round-trips it
// with no further change. Order fixes the struct layout -- append only.
#define HYBRID_M_EXT_CSR_LIST(X)                \
  X(menvcfg,         0x30A, "menvcfg")          \
  X(mseccfg,         0x747, "mseccfg")          \
  X(mcounteren,      0x306, "mcounteren")       \
  X(mcountinhibit,   0x320, "mcountinhibit")    \
  X(mhpmcounter3,    0xB03, "mhpmcounter3")     \
  X(mhpmcounter4,    0xB04, "mhpmcounter4")     \
  X(mhpmcounter5,    0xB05, "mhpmcounter5")     \
  X(mhpmcounter6,    0xB06, "mhpmcounter6")     \
  X(mhpmevent3,      0x323, "mhpmevent3")       \
  X(mhpmevent4,      0x324, "mhpmevent4")       \
  X(mhpmevent5,      0x325, "mhpmevent5")       \
  X(mhpmevent6,      0x326, "mhpmevent6")       \
  X(mcounterwen,     0x7CE, "mcounterwen")      \
  X(mcounterinten,   0x7CF, "mcounterinten")    \
  X(mcountermask_s,  0x7D2, "mcountermask_s")   \
  X(mcountermask_u,  0x7D3, "mcountermask_u")   \
  X(mnscratch,       0x740, "mnscratch")        \
  X(mnepc,           0x741, "mnepc")            \
  X(mncause,         0x742, "mncause")          \
  X(mnstatus,        0x744, "mnstatus")         \
  X(mnvec,           0x7C3, "mnvec")            \
  X(mrnxvec,         0x7DE, "mrnxvec")          \
  X(mdcause,         0x7C9, "mdcause")          \
  X(mslideleg,       0x7D5, "mslideleg")        \
  X(msavestatus,     0x7D6, "msavestatus")      \
  X(msaveepc1,       0x7D7, "msaveepc1")        \
  X(msavecause1,     0x7D8, "msavecause1")      \
  X(msaveepc2,       0x7D9, "msaveepc2")        \
  X(msavecause2,     0x7DA, "msavecause2")      \
  X(msavedcause1,    0x7DB, "msavedcause1")     \
  X(msavedcause2,    0x7DC, "msavedcause2")     \
  X(mtvt,            0x307, "mtvt")             \
  X(mintthresh,      0x347, "mintthresh")       \
  X(mcirq_entry,     0x7EC, "mcirq_entry")      \
  X(mstateen0,       0x30C, "mstateen0")        \
  X(mstateen1,       0x30D, "mstateen1")        \
  X(mstateen2,       0x30E, "mstateen2")        \
  X(mstateen3,       0x30F, "mstateen3")        \
  X(mcctlbeginaddr,  0x7CB, "mcctlbeginaddr")   \
  X(mcctldata,       0x7CD, "mcctldata")        \
  X(mppib,           0x7F0, "mppib")            \
  X(mfiob,           0x7F1, "mfiob")            \
  X(tselect,         0x7A0, "tselect")          \
  X(tdata1,          0x7A1, "tdata1")           \
  X(tdata2,          0x7A2, "tdata2")           \
  X(tcontrol,        0x7A5, "tcontrol")         \
  X(mcontext,        0x7A8, "mcontext")         \
  X(uzobctl,         0x808, "uzobctl")          \
  X(ucctlbeginaddr,  0x80B, "ucctlbeginaddr")   \
  X(sleepvalue,      0x811, "sleepvalue")       \
  X(umisc_ctl,       0x813, "umisc_ctl")

// Number of CSRs in HYBRID_M_EXT_CSR_LIST (locks the struct size in the checks).
#define HYBRID_M_EXT_CSR_NUM 51

struct hybrid_m_ext_csr {
#define HYBRID_M_EXT_FIELD(field, addr, name) uint64_t field;
  HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
#undef HYBRID_M_EXT_FIELD
};

// All fields are naturally 8-byte aligned, so __attribute__((packed)) is
// unnecessary and would force unaligned access codegen. Layout is locked by
// the static_asserts in state_abi_check.h.
struct hybrid_state_v1 {
  uint32_t magic;
  uint32_t version;
  uint32_t flags;
  uint32_t hart_id;
  uint64_t pc;
  uint64_t priv;  // 0=U, 1=S, 3=M

  uint64_t gpr[32];
  uint64_t fpr[32];

  uint64_t mstatus;
  uint64_t mepc;
  uint64_t mtvec;
  uint64_t mcause;
  uint64_t mtval;
  uint64_t mscratch;
  uint64_t medeleg;
  uint64_t mideleg;
  uint64_t mip;
  uint64_t mie;
  uint64_t mcycle;
  uint64_t minstret;
  uint64_t satp;

  uint64_t pmpcfg[HYBRID_PMP_CFG_NUM];
  uint64_t pmpaddr[HYBRID_PMP_ADDR_NUM];

  uint64_t vstart;
  uint64_t vtype;
  uint64_t vl;
  uint64_t vlenb;
  uint8_t  vreg[32 * HYBRID_VLEN_BYTES_MAX];
  uint64_t vxsat;
  uint64_t vxrm;
  uint64_t vcsr;

  // L20: FP control/status -- frm[7:5] | fflags[4:0], live when
  // HYBRID_FLAG_FP is set. Drained by the plugin, restored by ResumeDriver,
  // re-read by StateDrain. Pre-L20 state files carry 0 here (reserved bytes
  // are written as zero), which reads back as the reset value (RNE, no
  // flags) -- exactly the old behavior, so no version bump.
  uint64_t fcsr;

  // Andes machine-setup CSRs: mcache_ctl (0x7CA) enables the L1 I/D caches,
  // mmisc_ctl (0x7D0) holds misc machine config. crt0 writes them once at
  // boot; transporting them keeps the cycle engine from resuming caches-off
  // (ResumeDriver has the full rationale). Drained by the plugin, restored by
  // ResumeDriver, but NOT re-read by StateDrain: they are boot-static and the
  // drained value is unused (no QEMU2 leg). Old state files carry 0 here
  // (reset value), which is the pre-existing behavior, so no version bump.
  uint64_t mcache_ctl;
  uint64_t mmisc_ctl;

  // v3: Andes V5 CSR block (live when HYBRID_FLAG_ANDES). 31 * 8 = 248 bytes.
  struct hybrid_andes_csr andes;

  // v4: writable M-mode CSR block (live when HYBRID_FLAG_M_EXT). 51 * 8 = 408
  // bytes. Capability-gated per engine; transported forward-looking.
  struct hybrid_m_ext_csr m_ext;

  uint8_t  reserved[64];  // zero-initialise on write; v4-compatible growth room
};

#ifdef __cplusplus
}  // extern "C"
#endif

#include "hybrid/state_abi_check.h"

#endif  // HYBRID_STATE_ABI_H

